<template>
  <AuthLayout :loading="processing">
    <AuthCard
      :title="$t('headline')"
      :error="api_error ? error_message : ''"
    >
      <!-- First name -->
      <q-input
        v-model="firstName"
        dense
        outlined
        :label="$t('first_name')"
        data-cy="firstName"
        class="w-full"
        :error="!!firstNameError"
        :error-message="firstNameError ? $t(firstNameTran) : ''"
        hide-bottom-space
        @keyup.enter="enterS"
      />

      <!-- Last name -->
      <q-input
        v-model="lastName"
        dense
        outlined
        :label="$t('last_name')"
        data-cy="lastName"
        class="w-full"
        :error="!!lastNameError"
        :error-message="lastNameError ? $t(lastNameTran) : ''"
        hide-bottom-space
        @keyup.enter="enterS"
      />

      <!-- Email -->
      <q-input
        v-model="email"
        dense
        outlined
        :label="$t('email')"
        data-cy="email"
        class="w-full"
        :error="!!emailError"
        :error-message="emailError ? $t(emailTran) : ''"
        hide-bottom-space
        @keyup.enter="enterS"
      />

      <!-- Password -->
      <q-input
        v-model="password"
        dense
        outlined
        :label="$t('password')"
        :type="showPassword ? 'text' : 'password'"
        data-cy="password"
        data-test="password-input"
        class="w-full"
        :error="!!passwordError"
        :error-message="passwordError ? $t(passwordTran) : ''"
        hide-bottom-space
        @keyup.enter="enterS"
        @update:model-value="validatePassword"
      >
        <template v-slot:append>
          <button type="button" class="password-toggle" @click="toggleShow">
            <Icon
              :icon="showPassword ? 'mdi:eye-off-outline' : 'mdi:eye-outline'"
              class="size-5 text-muted-foreground"
            />
          </button>
        </template>
      </q-input>

      <!-- Password checklist -->
      <PasswordChecklist :password="password" @update:valid="isPasswordValid = $event" />

      <!-- Confirm password -->
      <q-input
        v-model="confirmPassword"
        dense
        outlined
        :label="$t('confirm_password')"
        :type="showConfPassword ? 'text' : 'password'"
        data-cy="confirmPassword"
        data-test="confirm-password-input"
        class="w-full"
        :error="!!confpasswordError"
        :error-message="confpasswordError ? $t(confPassTran) : ''"
        hide-bottom-space
        @keyup.enter="enterS"
        @update:model-value="checkPasswordMatch"
      >
        <template v-slot:append>
          <button type="button" class="password-toggle" @click="toggleShowConf">
            <Icon
              :icon="showConfPassword ? 'mdi:eye-off-outline' : 'mdi:eye-outline'"
              class="size-5 text-muted-foreground"
            />
          </button>
        </template>
      </q-input>

      <!-- Recaptcha -->
      <div v-if="recaptcha_key !== ''" class="captcha-box">
        <vue-recaptcha
          ref="recaptcha"
          :sitekey="recaptcha_key"
          @verify="captcaResp"
        />
        <span v-if="recaptchaKeyError" class="text-destructive text-xs ml-2">
          {{ $t(recaptchaTran) }}
        </span>
      </div>

      <!-- Terms & Conditions -->
      <div class="flex items-start gap-2">
        <q-checkbox
          v-model="agree"
          dense
          @keyup.enter="enterS"
        />
        <span class="text-sm text-muted-foreground leading-snug pt-0.5">
          {{ $t('terms_friendly') }}
          <span v-if="agreeError" class="text-destructive text-xs ml-1">
            {{ $t(agreeTran) }}
          </span>
        </span>
      </div>

      <template #actions>
        <q-btn
          unelevated
          color="primary"
          text-color="white"
          :disable="processing"
          :label="$t('register_button')"
          class="auth-submit-btn"
          @click="registerUser()"
        />

        <!-- Social login -->
        <div class="mt-4">
          <AuthDivider :text="$t('social_media')" />
          <div class="mt-3 flex justify-center gap-3">
            <GoogleLogin />
            <MicrosoftLogin />
          </div>
        </div>
      </template>
    </AuthCard>

    <template #footer>
      <div class="text-sm text-muted-foreground">
        {{ $t('have_account') }}
        <a class="text-primary font-medium cursor-pointer hover:underline" @click="user_login">
          {{ $t('login') }}
        </a>
      </div>
    </template>
  </AuthLayout>

  <!-- Error dialog -->
  <q-dialog v-model="display_error" persistent>
    <q-card class="rounded-xl" style="min-width: 400px">
      <q-card-section class="flex items-center justify-between p-4">
        <h3 class="text-lg font-semibold text-destructive">
          <Icon icon="mdi:alert-outline" class="size-5 mr-2 inline" />
          {{ $t('error') }}
        </h3>
        <q-btn flat round dense @click="display_error = false">
          <Icon icon="mdi:close" class="size-4" />
        </q-btn>
      </q-card-section>
      <q-card-section class="p-4 pt-0 text-sm text-foreground">
        {{ error_message }}
      </q-card-section>
      <q-card-actions align="right" class="p-4">
        <q-btn
          unelevated
          color="primary"
          text-color="white"
          :label="$t('Close')"
          @click="display_error = false"
        />
      </q-card-actions>
    </q-card>
  </q-dialog>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { LocalStorage } from 'quasar';
import { defineComponent, ref } from 'vue';
import { VueRecaptcha } from 'vue-recaptcha';
import { userApiService } from 'src/services';
import helperUtil from 'src/utils/helperUtil';
import { ApiExceptions } from 'src/exceptions';
import helperMixin from 'src/mixins/helperMixin.js';
import { specialChars, passwordPattern } from 'src/constants';
import GoogleLogin from 'src/pages/User/SocialMediaLogin/GoogleLogin.vue';
import MicrosoftLogin from 'src/pages/User/SocialMediaLogin/MicrosoftLogin.vue';
import { AuthLayout, AuthCard, AuthDivider, PasswordChecklist } from 'src/components/Auth';
export default defineComponent({
  mixins: [helperMixin, helperUtil],
  components: {
    VueRecaptcha,
    GoogleLogin,
    MicrosoftLogin,
    AuthLayout,
    AuthCard,
    AuthDivider,
    PasswordChecklist,
  },
  data() {
    return {
      lastName: '',
      firstName: '',
      email: '',
      password: '',
      confirmPassword: '',
      agree: false,
      emailError: '',
      passwordError: '',
      confpasswordError: '',
      agreeError: '',
      recaptchaKeyError: '',
      lastNameError: '',
      firstNameError: '',
      showPassword: false,
      showConfPassword: false,
      isPasswordValid: false,
      captchaResponse: ref(''),
      firstNameTran: '',
      lastNameTran: '',
      emailTran: '',
      passwordTran: '',
      confPassTran: '',
      recaptchaTran: '',
      agreeTran: '',
    };
  },
  setup() {
    return {
      api_error: ref(false),
      error_message: ref(''),
      display_error: ref(false),
      recaptcha_key: ref(''),
      processing: ref(false),
    };
  },
  mounted() {
    LocalStorage.remove('user_details');
    this.setRecaptchaKey();
  },
  methods: {
    validatePassword() {
      if (this.password && !this.isPasswordValid) {
        this.passwordError = 'Password does not meet requirements';
        this.passwordTran = 'password_invalid';
      } else {
        this.passwordError = '';
        this.passwordTran = '';
      }
    },

    privacyPolicy(URL: string) {
      window.open(URL);
    },

    setRecaptchaKey() {
      if (!process.env.APP_VUE_RECAPTCHA_KEY) {
        logInfo('Recaptcha key is missing');
        return;
      }
      this.recaptcha_key = process.env.APP_VUE_RECAPTCHA_KEY;
    },

    routeToVerifyEmail(email: string) {
      LocalStorage.set('verify_email', email);
      this.$router.push('/register-success');
    },

    enterS() {
      this.registerUser();
    },

    captcaResp(captResponse: any) {
      this.captchaResponse = captResponse;
    },

    toggleShow() {
      this.showPassword = !this.showPassword;
    },

    toggleShowConf() {
      this.showConfPassword = !this.showConfPassword;
    },

    user_login() {
      this.$router.push('/');
    },

    isValidPassword(password: any) {
      return passwordPattern.test(password);
    },

    validateForm() {
      let error = false;
      this.passwordError = '';
      this.confpasswordError = '';
      this.lastNameError = '';
      this.firstNameError = '';
      this.agreeError = '';
      this.emailError = '';
      this.recaptchaKeyError = '';
      this.firstNameTran = '';
      this.lastNameTran = '';
      this.emailTran = '';
      this.passwordTran = '';
      this.confPassTran = '';
      this.recaptchaTran = '';
      this.agreeTran = '';

      let standard_domains = [
        '@mail', '@google', '@gmail', '@hotmail', '@gmx',
        '@mailinator', '@microsoft', '@live', '@xbox', '@skype', '@outlook',
      ];

      if (this.firstName === '') {
        this.firstNameError = 'First name is required';
        this.firstNameTran = 'first_name_required';
        error = true;
      }

      if (this.lastName === '') {
        this.lastNameError = 'Last name is required';
        this.lastNameTran = 'last_name_required';
        error = true;
      }

      if (this.email === '') {
        this.emailError = 'Email is required';
        this.emailTran = 'email_required';
        error = true;
      }

      if (!this.validateEmail(this.email)) {
        this.emailError = 'Please enter valid email';
        this.emailTran = 'email_invalid';
        error = true;
      }

      if (standard_domains.some((d) => this.email.includes(d))) {
        notify.error(this.$t('personal_mail'));
        this.emailError = 'Please enter valid email';
        this.emailTran = 'email_invalid';
        error = true;
      }

      if (this.password === '') {
        this.passwordError = 'Password is required';
        this.passwordTran = 'password_required';
        error = true;
      }

      if (this.confirmPassword === '') {
        this.confpasswordError = 'Confirm password is required';
        this.confPassTran = 'confpass_required';
        error = true;
      }

      if (this.password && !this.isValidPassword(this.password)) {
        this.passwordError = 'Password does not meet requirements';
        this.passwordTran = 'password_invalid';
        error = true;
      }

      if (this.confirmPassword && !this.isValidPassword(this.confirmPassword)) {
        this.confpasswordError = 'Confirm password does not meet requirements';
        this.confPassTran = 'confpass_invalid';
        error = true;
      }

      if (
        this.password &&
        this.confirmPassword &&
        this.isValidPassword(this.confirmPassword) &&
        this.password !== this.confirmPassword
      ) {
        this.confpasswordError = 'Passwords do not match';
        this.confPassTran = 'pass_not_match';
        error = true;
      }

      if (this.agree === false) {
        this.agreeError = 'Please agree to the Terms and Conditions';
        this.agreeTran = 'agree_invalid';
        error = true;
      }

      if (!this.captchaResponse) {
        this.recaptchaKeyError = 'Please click if you are not a robot';
        this.recaptchaTran = 'recaptcha_invalid';
        error = true;
      }

      return error;
    },

    async registerUser() {
      try {
        let hasError = this.validateForm();
        if (!hasError) {
          this.processing = true;
          this.api_error = false;
          let data = {
            first_name: this.firstName,
            last_name: this.lastName,
            email: this.email,
            password: this.password,
            password_confirm: this.confirmPassword,
            captcha_response: this.captchaResponse,
          };
          let res = await userApiService.registerUser(data);
          this.processing = false;
          if (
            res &&
            res.hasOwnProperty('success') &&
            res.success === false &&
            res.hasOwnProperty('message')
          ) {
            this.displayErrorInDialog(res.message);
          }
          this.routeToVerifyEmail(this.email);
        }
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err);
        notify.error(msg);
      } finally {
        this.processing = false;
        this.resetRecaptcha();
      }
    },

    resetRecaptcha() {
      try {
        (<any>this).$refs['recaptcha'].reset();
      } catch (err: any) {
        logError(err);
      }
    },

    displayError(message: any) {
      if (message === '') return;
      this.api_error = true;
      this.error_message = message;
    },

    displayErrorInDialog(message: any) {
      this.display_error = true;
      this.error_message = message || this.$t('general_login_error');
    },

    checkPasswordMatch(confirmPassword: string) {
      this.confpasswordError = '';
      this.confPassTran = '';
      this.confirmPassword = confirmPassword;

      if (this.password && this.confirmPassword && this.password !== this.confirmPassword) {
        this.confpasswordError = 'Passwords do not match';
        this.confPassTran = 'pass_not_match';
      }

      this.validatePassword();
    },
  },
});
</script>

