  width: 100%;
  height: 44px;
  font-weight: 500;
  border-radius: 0.5rem;
}

.password-toggle {
  display: flex;
  align-items: center;
  background: none;
  border: none;
  cursor: pointer;
  padding: 0.25rem;

  &:hover {
    opacity: 0.7;
  }
}

.captcha-box {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.5rem;
  border-radius: 0.5rem;
  background-color: var(--muted);
  border: 1px solid var(--border);
}
</style>
